INSERT INTO question_option_translations(option_id,locale,label,description) SELECT o.id,'bg','Дистанционно','Специалистът може да предостави услугата онлайн.' FROM question_options o JOIN service_questions q ON q.id=o.question_id JOIN marketplace_services s ON s.id=q.service_id WHERE s.code='WEBSITE_DEVELOPMENT' AND q.question_key='delivery_mode' AND o.option_value='REMOTE';
INSERT INTO question_option_translations(option_id,locale,label,description) SELECT o.id,'bg','На място','Специалистът трябва да дойде на мястото, където ще се извърши услугата.' FROM question_options o JOIN service_questions q ON q.id=o.question_id JOIN marketplace_services s ON s.id=q.service_id WHERE s.code='WEBSITE_DEVELOPMENT' AND q.question_key='delivery_mode' AND o.option_value='ON_SITE';
INSERT INTO question_option_translations(option_id,locale,label,description) SELECT o.id,'bg','Гъвкаво','Подходящо е както дистанционна работа, така и работа на място.' FROM question_options o JOIN service_questions q ON q.id=o.question_id JOIN marketplace_services s ON s.id=q.service_id WHERE s.code='WEBSITE_DEVELOPMENT' AND q.question_key='delivery_mode' AND o.option_value='FLEXIBLE';
